配置数学公式渲染 下载KaTeX 地址：https://cdn.jsdelivr.net/npm/katex@0.16.11/dist/
我们直接在项目的根目录中执行npm install katex@0.16.11
安装完成后，node_modules/katex/dist/ 里面就是完整 dist，把里面全部复制到 static/katex/ 修改根目录下的layouts/partials/extend_head.html {{ if or .Params.math .Site.Params.math }} &lt;link rel=&#34;stylesheet&#34; href=&#34;/katex/katex.min.css&#34;&gt; &lt;script defer src=&#34;/katex/katex.min.js&#34;&gt;&lt;/script&gt; &lt;script defer src=&#34;/katex/contrib/auto-render.min.js&#34;&gt;&lt;/script&gt; &lt;script&gt; document.addEventListener(&#34;DOMContentLoaded&#34;, function() { renderMathInElement(document.body,{ delimiters: [ {left: &#39;$$&#39;, right: &#39;$$&#39;, display: true}, {left: &#39;$&#39;, right: &#39;$&#39;, display: false} ] }); }); &lt;/script&gt; {{ end }} 配置hugo.yml markup: goldmark: renderer: unsafe: true extensions: passthrough: enable: true delimiters: block: - - &#34;$$&#34; - &#34;$$&#34; inline: - - &#34;$&#34; - &#34;$&#34; 配置目录在右侧 在根目录下的assets/css/extended/toc.css创建一个toc.css /* assets/css/extended/toc.css */ .toc-sidebar { /* 脱离文档流，不会挤压文章 */ position: fixed; top: 150px; right: 200px; width: 240px; max-height: 85vh; overflow-y: auto; padding: 1rem; z-index: 10; /* 可选：增加半透明背景，防止文字重叠看不清 */ background: var(--theme); // 让背景和主题一个颜色，方便主题颜色切换 border-radius: 8px; } .toc-sidebar .toc { background: var(--theme); border: 0px solid var(--border); } /* 小屏幕直接隐藏这个固定目录 */ @media (max-width: 1200px) { .toc-sidebar { display: none !important; } } .toc-sidebar #TableOfContents { font-size: 0.9rem; } .toc-sidebar #TableOfContents ul { padding-left: 1rem; list-style: none; /* 去掉前面的小圆点*/ } .toc-marker { margin-right: 0.3rem; opacity: 0.6; } .toc-expanded&gt;a { font-weight: bold; } 将根目录下的layouts/_default/single.html 替换成下面 {{- define &#34;main&#34; }} &lt;div class=&#34;post-single-wrapper&#34;&gt; &lt;article class=&#34;post-single&#34;&gt; &lt;header class=&#34;post-header&#34;&gt; {{ partial &#34;breadcrumbs.html&#34; . }} &lt;h1 class=&#34;post-title entry-hint-parent&#34;&gt; {{ .Title }} {{- if .Draft }} &lt;span class=&#34;entry-hint&#34; title=&#34;Draft&#34;&gt; &lt;svg xmlns=&#34;http://www.w3.org/2000/svg&#34; height=&#34;35&#34; viewBox=&#34;0 -960 960 960&#34; fill=&#34;currentColor&#34;&gt; &lt;path d=&#34;M160-410v-60h300v60H160Zm0-165v-60h470v60H160Zm0-165v-60h470v60H160Zm360 580v-123l221-220q9-9 20-13t22-4q12 0 23 4.5t20 13.5l37 37q9 9 13 20t4 22q0 11-4.5 22.5T862.09-380L643-160H520Zm300-263-37-37 37 37ZM580-220h38l121-122-18-19-19-18-122 121v38Zm141-141-19-18 37 37-18-19Z&#34; /&gt; &lt;/svg&gt; &lt;/span&gt; {{- end }} &lt;/h1&gt; {{- if .Description }} &lt;div class=&#34;post-description&#34;&gt; {{ .Description }} &lt;/div&gt; {{- end }} {{- if not (.Param &#34;hideMeta&#34;) }} &lt;div class=&#34;post-meta&#34;&gt; {{- partial &#34;post_meta.html&#34; . -}} {{- partial &#34;translation_list.html&#34; . -}} {{- partial &#34;edit_post.html&#34; . -}} {{- partial &#34;post_canonical.html&#34; . -}} &lt;/div&gt; {{- end }} &lt;/header&gt; {{- $isHidden := (.Param &#34;cover.hiddenInSingle&#34;) | default (.Param &#34;cover.hidden&#34;) | default false }} {{- partial &#34;cover.html&#34; (dict &#34;cxt&#34; . &#34;IsSingle&#34; true &#34;isHidden&#34; $isHidden) }} {{- if .Content }} &lt;div class=&#34;post-content md-content&#34;&gt; {{- if not (.Param &#34;disableAnchoredHeadings&#34;) }} {{- partial &#34;anchored_headings.html&#34; .Content -}} {{- else }}{{ .Content }}{{ end }} &lt;/div&gt; {{- end }} &lt;footer class=&#34;post-footer&#34;&gt; {{- $tags := .Language.Params.Taxonomies.tag | default &#34;tags&#34; }} &lt;ul class=&#34;post-tags&#34;&gt; {{- range ($.GetTerms $tags) }} &lt;li&gt;&lt;a href=&#34;{{ .Permalink }}&#34;&gt;{{ .LinkTitle }}&lt;/a&gt;&lt;/li&gt; {{- end }} &lt;/ul&gt; {{- if (.Param &#34;ShowPostNavLinks&#34;) }} {{- partial &#34;post_nav_links.html&#34; . }} {{- end }} {{- if (and site.Params.ShowShareButtons (ne .Params.disableShare true)) }} {{- partial &#34;share_icons.html&#34; . -}} {{- end }} &lt;/footer&gt; {{- if (.Param &#34;comments&#34;) }} {{- partial &#34;comments.html&#34; . }} {{- end }} &lt;/article&gt; &lt;/div&gt; {{- if (.Param &#34;ShowToc&#34;) }} &lt;aside class=&#34;toc-sidebar&#34;&gt; {{- partial &#34;toc.html&#34; . }} &lt;script&gt; document.addEventListener(&#39;DOMContentLoaded&#39;, function() { var nav = document.querySelector(&#39;.toc-sidebar #TableOfContents&#39;); if (!nav) return; nav.querySelectorAll(&#39;li&#39;).forEach(function(li) { var sub = li.querySelector(&#39;ul&#39;); if (!sub) return; var a = li.querySelector(&#39;a&#39;); if (!a) return; var level = 0; var el = a.parentNode; while (el &amp;&amp; el !== nav) { if (el.tagName === &#39;UL&#39;) level++; el = el.parentNode; } // 会在目录前面加上#号 // var marker = document.createElement(&#39;span&#39;); // marker.className = &#39;toc-marker&#39;; // marker.textContent = &#39;#&#39;.repeat(level + 1); // a.parentNode.insertBefore(marker, a); }); nav.querySelectorAll(&#39;li&#39;).forEach(function(li) { var sub = li.querySelector(&#39;ul&#39;); if (!sub) return; sub.style.display = &#39;none&#39;; li.addEventListener(&#39;click&#39;, function(e) { if (e.target.tagName === &#39;A&#39;) e.preventDefault(); var isOpen = sub.style.display !== &#39;none&#39;; sub.style.display = isOpen ? &#39;none&#39; : &#39;block&#39;; li.classList.toggle(&#39;toc-expanded&#39;, !isOpen); }); }); }); &lt;/script&gt; &lt;/aside&gt; {{- end }} {{- end }}{{/* end main */}}
